/** 個別記事がある食材名かどうか（別名は正規品の記事に解決するので true） */
export function hasOwnKnowledge(name) {
  const n = String(name || "");
  if (Object.prototype.hasOwnProperty.call(KNOWLEDGE, n)) return true;
  const canon = KNOWLEDGE_ALIASES[n];
  if (canon && Object.prototype.hasOwnProperty.call(KNOWLEDGE, canon)) return true;
  const variant = resolveCanonicalName(n);
  return variant !== n && Object.prototype.hasOwnProperty.call(KNOWLEDGE, variant);
}

function hashOf(s) {
  let h = 0;
  for (const ch of String(s)) h = (h * 31 + ch.codePointAt(0)) >>> 0;
  return h;
}

/**
 * 食材の知識を返す。個別記事 → カテゴリ共通の順で解決し、
 * カタログ全品に必ず { body, season, choose, trivia[], quiz } が返る。
 */
export function knowledgeFor(name, category) {
  const n = String(name || "");
  const own = KNOWLEDGE[n];
  if (own) return { name: n, source: "item", ...own };
  const aliasTarget = KNOWLEDGE_ALIASES[n];
  if (aliasTarget && KNOWLEDGE[aliasTarget]) return { name: n, source: "item", ...KNOWLEDGE[aliasTarget] };
  const variantTarget = resolveCanonicalName(n);
  if (variantTarget !== n && KNOWLEDGE[variantTarget]) return { name: n, source: "item", ...KNOWLEDGE[variantTarget] };
  const cat = CATEGORY_KNOWLEDGE[category] || CATEGORY_KNOWLEDGE["その他"];
  const fill = (s) => String(s).replaceAll("{name}", n);
  return {
    name: n,
    source: "category",
    body: fill(cat.body),
    season: fill(cat.season),
    choose: fill(cat.choose),
    trivia: cat.trivia.map(fill),
    quiz: cat.quizzes[hashOf(n) % cat.quizzes.length],
  };
}
